/// Computes the triangular number of a given non-negative integer n.
fn triangle(n: u32) -> u32 {
    if n == 0 {
        0
    } else {
        n * (n + 1) / 2 // Using the formula T(n) = n * (n + 1) / 2
    }
}

/// Proves that the triangular number function is monotonic: if i ≤ j then triangle(i) ≤ triangle(j).
fn triangle_is_monotonic(i: u32, j: u32) -> bool {
    if i > j {
        return false;
    }
    triangle(i) <= triangle(j)
}

/// Tail-recursive procedure to compute the triangular number using an accumulator.
fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    if idx > n {
        return; // Base case: if the current index exceeds the target, terminate.
    }
    *sum += idx; // Update the accumulator with the current index.
    tail_triangle(n, idx + 1, sum); // Recursive call with the next index.
}

fn main() {
    let n: u32 = 5; // Example input
    let mut sum: u32 = 0;
    tail_triangle(n, 1, &mut sum); // Start the tail-recursive function
    println!("The triangular number of {} is {}", n, sum); // Output the result
}